SET SESSION lock_wait_timeout = 5;
ALTER TABLE orders ADD COLUMN note TEXT, ALGORITHM=INSTANT;
ALTER TABLE orders ADD INDEX idx_created (created_at), ALGORITHM=INPLACE, LOCK=NONE;
ALTER TABLE orders MODIFY COLUMN name VARCHAR(200), ALGORITHM=INPLACE, LOCK=NONE;
UPDATE orders SET status = 'new' WHERE id BETWEEN 1 AND 5000;
